-- Lot 206 : payloads 151 a 180 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-018","moteur":"chatgpt","payload":"[RaccourcIA — /thumbnail]\n\nMISSION\nGenerer une miniature accrocheuse sans tromper le sujet. Un sujet dominant, une tension visuelle liée au contenu réel et deux à cinq mots maximum. Évite les expressions trompeuses et les éléments absents de la vidéo.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel message unique doit être compris en premier ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Miniature virale » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Un sujet dominant, une tension visuelle liée au contenu réel et deux à cinq mots maximum. Évite les expressions trompeuses et les éléments absents de la vidéo. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"e0e379548c75cd55db842df815a3430251868e8c697c33c78d958989553a39b7"},{"ref":"RCI-IMG-018","moteur":"claude","payload":"[RaccourcIA — /thumbnail]\n\nMISSION\nGenerer une miniature accrocheuse sans tromper le sujet. Un sujet dominant, une tension visuelle liée au contenu réel et deux à cinq mots maximum. Évite les expressions trompeuses et les éléments absents de la vidéo.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel message unique doit être compris en premier ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Miniature virale » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Un sujet dominant, une tension visuelle liée au contenu réel et deux à cinq mots maximum. Évite les expressions trompeuses et les éléments absents de la vidéo. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"5e997695d86fde7e01a841b18c3a40530ec12ca7ae4d728a46ab581200863c04"},{"ref":"RCI-IMG-018","moteur":"gemini","payload":"[RaccourcIA — /thumbnail]\n\nMISSION\nGenerer une miniature accrocheuse sans tromper le sujet. Un sujet dominant, une tension visuelle liée au contenu réel et deux à cinq mots maximum. Évite les expressions trompeuses et les éléments absents de la vidéo.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel message unique doit être compris en premier ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Miniature virale » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Un sujet dominant, une tension visuelle liée au contenu réel et deux à cinq mots maximum. Évite les expressions trompeuses et les éléments absents de la vidéo. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"bf04f269c6a0a971ad7616ccf925fd29cc8ff8d78b2203c9777674600d8f2f11"},{"ref":"RCI-IMG-019","moteur":"chatgpt","payload":"[RaccourcIA — /poster]\n\nMISSION\nTransformer un sujet en affiche propre et expressive. Une image principale, un titre lisible à distance et un bloc utile. Le message précède les détails, sans fausse date ni organisme inventé.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « message » ? puis Quel type d’affiche faut-il produire : événement, lancement, produit, restauration ou promotion ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Affiche impact » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Une image principale, un titre lisible à distance et un bloc utile. Le message précède les détails, sans fausse date ni organisme inventé. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /poster: Une image principale, un titre lisible à distance et un bloc utile. Le message précède les détails, sans fausse date ni organisme inventé. Mode /eventposter: Un concept visuel lié à l’événement, puis nom, date, lieu et réservation. Vérifie chaque information avant de l’inscrire. Mode /foodposter: Valorise texture, lumière et présentation réelles, puis nom et prix si fournis. N’augmente pas artificiellement la portion ou les ingrédients vendus. Mode /holidaycreative: Choisis deux signes festifs pertinents et garde le produit dominant. Demande l’occasion si elle manque; n’invente pas de promotion liée à la fête. Mode /launchposter: Construis un dévoilement lumineux du produit, un nom clair et une date uniquement si fournie. Pas de fausse urgence ni disponibilité supposée. Mode /productposter: Produit dominant et métaphore liée à son usage, titre très court si nécessaire. Distingue cette affiche d’un packshot neutre. Mode /promoflyer: Offre, conditions, période et contact sont hiérarchisés dans cet ordre selon le contexte. Ne remplis aucun champ factuel sans source. Mode /salegraphic: Le produit reste dominant, la réduction est exacte et la période visible. Vérifie la cohérence prix initial, prix final et pourcentage si ces trois valeurs sont fournies. Mode /streetposter: Un motif distinctif, cinq mots environ et une signature. Fais primer contraste et reconnaissance à distance sur les effets décoratifs. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"d1073adb279c20f2adff869d2cf45058d585ab0ad5e671e7cb76bcf69642fe88"},{"ref":"RCI-IMG-019","moteur":"claude","payload":"[RaccourcIA — /poster]\n\nMISSION\nTransformer un sujet en affiche propre et expressive. Une image principale, un titre lisible à distance et un bloc utile. Le message précède les détails, sans fausse date ni organisme inventé.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « message » ? puis Quel type d’affiche faut-il produire : événement, lancement, produit, restauration ou promotion ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Affiche impact » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Une image principale, un titre lisible à distance et un bloc utile. Le message précède les détails, sans fausse date ni organisme inventé. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /poster: Une image principale, un titre lisible à distance et un bloc utile. Le message précède les détails, sans fausse date ni organisme inventé. Mode /eventposter: Un concept visuel lié à l’événement, puis nom, date, lieu et réservation. Vérifie chaque information avant de l’inscrire. Mode /foodposter: Valorise texture, lumière et présentation réelles, puis no